/**
 * Runtime support for Move bindings generated by `@unconfirmed/sui-codegen`,
 * also usable by hand.
 *
 * - Built-in BCS schemas for well-known framework types (`UID`, `Coin`,
 *   `Balance`, `Table`, `VecMap`, ...). Generated code refers to these instead
 *   of regenerating the framework in every project.
 * - Argument helpers that turn plain TS values (or `Ptb` arguments) into
 *   inputs: `obj`, `pure`, `option`, `param` (a generic `T`), and the
 *   auto-filled system objects (`clock`, `random`, `denyList`, `system`,
 *   `accumulatorRoot`), which match what `@mysten/sui` fills in.
 * - `call`: one Move call against a package id held in a `Context.Reference`.
 * - `datatype` / `object` / `generic`: attach a Move type-string helper (and,
 *   for `key` structs, a `get` that reads and decodes the object) to a schema.
 *
 * Nothing here reflects over Move metadata at runtime: the generator emits the
 * schemas and argument kinds; these helpers only do the plumbing.
 */
import type * as Context from "effect/Context"
import * as Effect from "effect/Effect"
import * as Option from "effect/Option"
import * as Schema from "effect/Schema"
import * as Bcs from "@unconfirmed/bcs/Bcs"
import * as Address from "./Address.ts"
import * as Objects from "./Objects.ts"
import * as Ptb from "./Ptb.ts"
import type { RpcError } from "./RpcError.ts"
import type * as T from "./TransactionData.ts"
import * as TypeTag from "./TypeTag.ts"

// -----------------------------------------------------------------------------
// Well-known framework types
// -----------------------------------------------------------------------------

/** `0x2::object::UID`, flattened to its address. */
export const UID = Bcs.Address
/** `0x2::object::ID`, flattened to its address. */
export const ID = Bcs.Address
/** `0x1::type_name::TypeName`. */
export const TypeName = /* @__PURE__ */ Bcs.struct({ name: Bcs.string })
/** `0x2::url::Url`. */
export const Url = /* @__PURE__ */ Bcs.struct({ url: Bcs.string })
/** `0x2::balance::Balance<phantom T>`. */
export const Balance = /* @__PURE__ */ Bcs.struct({ value: Bcs.u64 })
/** `0x2::coin::Coin<phantom T>`. */
export const Coin = /* @__PURE__ */ Bcs.struct({ id: UID, balance: Balance })
/** `0x2::table::Table<phantom K, phantom V>`: a handle; entries are dynamic fields of `id`. */
export const Table = /* @__PURE__ */ Bcs.struct({ id: UID, size: Bcs.u64 })
/** `0x2::bag::Bag`. */
export const Bag = Table
/** `0x2::object_table::ObjectTable<phantom K, phantom V>`. */
export const ObjectTable = Table
/** `0x2::object_bag::ObjectBag`. */
export const ObjectBag = Table
/** `0x2::table_vec::TableVec<phantom E>`. */
export const TableVec = /* @__PURE__ */ Bcs.struct({ contents: Table })
/** `0x2::vec_map::VecMap<K, V>`. */
export const VecMap = <K extends Schema.Top, V extends Schema.Top>(K: K, V: V) =>
  Bcs.struct({ contents: Bcs.vector(Bcs.struct({ key: K, value: V })) })
/** `0x2::vec_set::VecSet<K>`. */
export const VecSet = <K extends Schema.Top>(K: K) => Bcs.struct({ contents: Bcs.vector(K) })
/** `0x2::linked_table::LinkedTable<K, phantom V>`. */
export const LinkedTable = <K extends Schema.Top>(K: K) =>
  Bcs.struct({ id: UID, size: Bcs.u64, head: Bcs.option(K), tail: Bcs.option(K) })
/** `0x2::dynamic_field::Field<N, V>`. */
export const Field = <N extends Schema.Top, V extends Schema.Top>(N: N, V: V) =>
  Bcs.struct({ id: UID, name: N, value: V })

/**
 * An address as a pure argument: any `0x` hex (`"0x2"` included), normalized
 * when encoded. Invalid hex is a typed `InvalidPureValue`.
 */
export const address: Bcs.BcsSchema<string, string> = /* @__PURE__ */ Bcs.transform(
  Bcs.Address,
  /* @__PURE__ */ Schema.String.check(/* @__PURE__ */ Schema.isPattern(/^(0x|0X)?[0-9a-fA-F]{1,64}$/)),
  { decode: (a) => a, encode: (s) => Address.normalize(s) }
) as any

// -----------------------------------------------------------------------------
// Type strings and object reads
// -----------------------------------------------------------------------------

/** A Move type string from its type arguments (all of them, phantom ones included). */
export type TypeFn = (...typeArguments: ReadonlyArray<string>) => string

export type Get<A> = (objectId: string) => Effect.Effect<
  A,
  Objects.ObjectNotFound | Objects.ObjectDecodeError | RpcError,
  Objects.Objects
>

/** Read an object and decode its contents (`Objects.getAs`), with a lenient id. */
export const get = <A, E>(objectId: string, schema: Schema.Codec<A, E>) =>
  Effect.suspend(() => Objects.getAs(Address.normalize(objectId), schema))

/**
 * A datatype schema with its Move type string: `Status.type()`. The schema is
 * built by a thunk so that, under `/* @__PURE__ *\/`, an unused datatype is
 * dropped whole by every bundler (esbuild keeps unannotated nested calls).
 */
export const datatype = <F extends TypeFn, S extends Schema.Top>(type: F, schema: () => S): S & { readonly type: F } =>
  Object.assign(copy(schema()), { type })

/**
 * A shallow copy of a schema (same prototype, same AST), so attaching `type` or
 * `get` never rewrites a schema shared elsewhere (`Move.Table` is also `Bag`).
 */
const copy = <S extends Schema.Top>(schema: S): S => Object.assign(Object.create(Object.getPrototypeOf(schema)), schema)

/** Attach `get(objectId)` to a `key` struct's schema (a copy; the given schema is unchanged). */
export const withGet = <S extends Schema.Top>(schema: S): S & { readonly get: Get<S["Type"]> } =>
  Object.assign(copy(schema), { get: (objectId: string) => get(objectId, schema as unknown as Schema.Codec<S["Type"]>) })

/** A `key` struct: `Thing.type()` and `Thing.get(objectId)`. */
export const object = <F extends TypeFn, S extends Schema.Top>(
  type: F,
  schema: () => S
): S & { readonly type: F; readonly get: Get<S["Type"]> } => datatype(type, () => withGet(schema()))

/**
 * A generic datatype: a function of its non-phantom type parameters' schemas,
 * plus `type(...allTypeArguments)`.
 */
export const generic = <F extends TypeFn, Make extends (...schemas: ReadonlyArray<any>) => Schema.Top>(
  type: F,
  make: Make
): Make & { readonly type: F } => Object.assign(((...schemas: ReadonlyArray<any>) => make(...schemas)) as Make, { type })

/** The decoded type of a schema: `Move.TypeOf<typeof Pair<Schema.Codec<number>, ...>>`. */
export type TypeOf<F> = F extends (...args: ReadonlyArray<any>) => infer S ? S extends Schema.Top ? S["Type"] : never
  : F extends Schema.Top ? F["Type"]
  : never

// -----------------------------------------------------------------------------
// Arguments
// -----------------------------------------------------------------------------

export type Argument = T.Argument

/** A shared object whose initial shared version is known: no lookup, and the input is added in parameter order. */
export interface SharedRef {
  readonly objectId: string
  readonly initialSharedVersion: bigint
  readonly mutable: boolean
}

/**
 * An object parameter:
 * - an object id (the resolver looks it up);
 * - a `SharedRef` (`{ objectId, initialSharedVersion, mutable }`) or an owned
 *   `Ptb.ObjectReference` (`{ objectId, version, digest }`), used as given;
 * - an argument (an earlier result, an input already added);
 * - an unrun step that makes the argument (`Ptb.receiving(ref)`,
 *   `Ptb.sharedObject(...)`, `Ptb.object(id, { mutable })`).
 *
 * Everything but an argument becomes an input when the call adds its
 * arguments, in parameter order, so the inputs line up as `@mysten/sui` adds
 * them for the same call. Inputs are deduplicated by object id.
 */
export type ObjectInput =
  | string
  | Argument
  | SharedRef
  | Ptb.ObjectReference
  | Effect.Effect<Argument, Ptb.InvalidPureValue, Ptb.PtbBuilder>

/** A pure parameter: the plain value, or an argument. */
export type Input<V> = V | Argument

/** An `Option<T>` parameter: an `Option`, a bare value (`Some`), `undefined` (`None`), or an argument. */
export type OptionInput<V> = Option.Option<V> | V | undefined | Argument

/** A value for a generic `T` parameter: encoded by the type argument when it's pure, else an object (`ObjectInput`). */
export type GenericInput =
  | ObjectInput
  | string
  | number
  | bigint
  | boolean
  | Uint8Array
  | ReadonlyArray<unknown>
  | Option.Option<unknown>
  | undefined

type Arg<E = never> = Effect.Effect<Argument, E, Ptb.PtbBuilder>

const ARGUMENT_TAGS = new Set(["GasCoin", "Input", "Result", "NestedResult"])

export const isArgument = (u: unknown): u is Argument =>
  typeof u === "object" && u !== null && !Array.isArray(u) && ARGUMENT_TAGS.has((u as { _tag?: unknown })._tag as string)

/** Pick the positional or named form of `arguments`. */
export const isTuple = <A>(a: A): a is Extract<A, ReadonlyArray<unknown>> => Array.isArray(a)

/** An object parameter (`ObjectInput`). An id becomes an object input the resolver looks up. */
export const obj = (input: ObjectInput): Arg<Ptb.InvalidPureValue> =>
  typeof input === "string"
    ? Ptb.object(input)
    : Effect.isEffect(input)
    ? input
    : isArgument(input)
    ? Effect.succeed(input)
    : "initialSharedVersion" in input
    ? Ptb.sharedObject(input.objectId, input.initialSharedVersion, input.mutable)
    : Ptb.owned(input)

/** A pure parameter, encoded by its schema. */
export const pure = <A, E>(schema: Schema.Codec<A, E>, input: A | Argument): Arg<Ptb.InvalidPureValue> =>
  isArgument(input) ? Effect.succeed(input) : Ptb.pure(schema, input)

/** An `Option<T>` parameter. */
export const option = <A, E>(item: Schema.Codec<A, E>, input: OptionInput<A>): Arg<Ptb.InvalidPureValue> =>
  isArgument(input)
    ? Effect.succeed(input)
    : Ptb.pure(
      Bcs.option(item) as unknown as Schema.Codec<Option.Option<A>>,
      Option.isOption(input) ? input as Option.Option<A> : input === undefined ? Option.none() : Option.some(input as A)
    )

type PureStruct = (args: ReadonlyArray<TypeTag.TypeTag>) => Schema.Top | undefined

/** Pure struct types by full name, built on first use so an unused `Move` import costs nothing at load. */
let pureStructs: Record<string, PureStruct> | undefined
const PURE_STRUCTS = (): Record<string, PureStruct> => pureStructs ??= {
  [`${Address.normalize("0x1")}::string::String`]: () => Bcs.string,
  [`${Address.normalize("0x1")}::ascii::String`]: () => Bcs.string,
  [`${Address.normalize("0x2")}::object::ID`]: () => address,
  [`${Address.normalize("0x1")}::option::Option`]: ([inner]) => {
    const s = inner === undefined ? undefined : pureSchemaOf(inner)
    return s === undefined ? undefined : Bcs.option(s)
  }
}

/** The BCS schema of a pure type tag (`u64`, `vector<address>`, `0x1::string::String`, ...), or `undefined`. */
export const pureSchemaOf = (tag: TypeTag.TypeTag): Schema.Top | undefined => {
  switch (tag._tag) {
    case "bool":
      return Bcs.bool
    case "u8":
      return Bcs.u8
    case "u16":
      return Bcs.u16
    case "u32":
      return Bcs.u32
    case "u64":
      return Bcs.u64
    case "u128":
      return Bcs.u128
    case "u256":
      return Bcs.u256
    case "address":
      return address
    case "signer":
      return undefined
    case "vector": {
      if (tag.value._tag === "u8") return Bcs.byteVector
      const item = pureSchemaOf(tag.value)
      return item === undefined ? undefined : Bcs.vector(item)
    }
    case "struct":
      return PURE_STRUCTS()[`${tag.address}::${tag.module}::${tag.name}`]?.(tag.typeParams)
  }
}

/**
 * A parameter typed by a function type parameter: pure when its type argument
 * is (`u64`, `vector<u8>`, `0x1::string::String`, `Option<...>`), else an object.
 */
export const param = (typeArgument: string, input: GenericInput): Arg<Ptb.InvalidPureValue> =>
  Effect.suspend(() => {
    if (isArgument(input)) return Effect.succeed(input)
    if (Effect.isEffect(input) || (typeof input === "object" && input !== null && "objectId" in input)) {
      return obj(input as ObjectInput)
    }
    let tag: TypeTag.TypeTag
    try {
      tag = TypeTag.parse(typeArgument)
    } catch (e) {
      return Effect.fail(new Ptb.InvalidPureValue({ issue: e instanceof Error ? e.message : String(e) }))
    }
    const schema = pureSchemaOf(tag)
    if (schema !== undefined) {
      const isOption = schema !== undefined && Bcs.layoutOf(schema)._tag === "option"
      const value = isOption && !Option.isOption(input)
        ? input === undefined ? Option.none() : Option.some(input)
        : input
      return Ptb.pure(schema as unknown as Schema.Codec<unknown>, value)
    }
    if (typeof input === "string") return Ptb.object(input)
    return Effect.fail(new Ptb.InvalidPureValue({ issue: `expected an object id or an argument for ${typeArgument}` }))
  })

// -----------------------------------------------------------------------------
// Auto-filled system objects (as `@mysten/sui`'s `tx.object.clock()` etc.)
// -----------------------------------------------------------------------------

const CLOCK = Address.CLOCK
const RANDOM = Address.RANDOM
const SYSTEM_STATE = /* @__PURE__ */ Address.normalize("0x5")
const DENY_LIST = /* @__PURE__ */ Address.normalize("0x403")
const ACCUMULATOR_ROOT = /* @__PURE__ */ Address.normalize("0xacc")

/** A shared object whose initial shared version is known, deduplicated by id like `Ptb.object`. */
export const shared = (objectId: string, initialSharedVersion: bigint, mutable: boolean): Arg<Ptb.InvalidPureValue> =>
  Ptb.sharedObject(objectId, initialSharedVersion, mutable)

/** `&Clock` (0x6): shared, initial version 1, immutable. */
export const clock = (input?: ObjectInput): Arg<Ptb.InvalidPureValue> => input === undefined ? shared(CLOCK, 1n, false) : obj(input)

/** `&Random` (0x8): immutable; its initial version is looked up. */
export const random = (input?: ObjectInput): Arg<Ptb.InvalidPureValue> =>
  input === undefined ? Ptb.object(RANDOM, { mutable: false }) : obj(input)

/** `&DenyList` / `&mut DenyList` (0x403): mutability from the function signature. */
export const denyList = (input?: ObjectInput): Arg<Ptb.InvalidPureValue> => input === undefined ? Ptb.object(DENY_LIST) : obj(input)

/** `&SuiSystemState` / `&mut SuiSystemState` (0x5): shared, initial version 1. */
export const system = (mutable: boolean, input?: ObjectInput): Arg<Ptb.InvalidPureValue> =>
  input === undefined ? shared(SYSTEM_STATE, 1n, mutable) : obj(input)

/** `&AccumulatorRoot` (0xacc). */
export const accumulatorRoot = (input?: ObjectInput): Arg<Ptb.InvalidPureValue> =>
  input === undefined ? Ptb.object(ACCUMULATOR_ROOT) : obj(input)

// -----------------------------------------------------------------------------
// Calls
// -----------------------------------------------------------------------------

/** A tuple of `N` arguments: the results of a Move call that returns `N` values. */
export type Results<N extends number, Acc extends ReadonlyArray<Argument> = readonly []> = Acc["length"] extends N
  ? Acc
  : Results<N, readonly [...Acc, Argument]>

/**
 * `<package>::<target>` with arguments added in parameter order. The package id
 * comes from `pkg` (a `Context.Reference`, so it needs nothing in `R`), and the
 * results are `NestedResult`s, one per Move return value.
 */
export const call = <const N extends number, E = never>(
  pkg: Context.Reference<string>,
  target: `${string}::${string}`,
  typeArguments: ReadonlyArray<string>,
  args: ReadonlyArray<Effect.Effect<Argument, E, Ptb.PtbBuilder>>,
  returns: N
): Effect.Effect<Results<N>, E | Ptb.InvalidPureValue, Ptb.PtbBuilder> =>
  Effect.gen(function*() {
    const id = yield* pkg
    const resolved: Array<Argument> = []
    for (const a of args) resolved.push(yield* a)
    const result = yield* Ptb.moveCall({
      target: `${id}::${target}` as `${string}::${string}::${string}`,
      typeArguments,
      arguments: resolved
    })
    return Array.from({ length: returns }, (_, i) => Ptb.nested(result, i)) as unknown as Results<N>
  })
